package com.witchersbestiary.fist;
import net.minecraft.network.*;import net.minecraft.network.codec.*;import net.minecraft.network.packet.CustomPayload;import net.minecraft.util.Identifier;import net.minecraft.server.network.ServerPlayerEntity;
public final class FistPackets{
 public record Action(int value) implements CustomPayload{public static final Id<Action>ID=new Id<>(Identifier.of("witchersbestiary:fist_action"));public static final PacketCodec<RegistryByteBuf,Action>CODEC=PacketCodec.of((p,b)->b.writeVarInt(p.value),b->new Action(b.readVarInt()));public Id<Action>getId(){return ID;}}
 public record State(boolean active,int npc,int stage,float health,float stamina,float maxStamina,float playerHealth,String name,String action) implements CustomPayload{public static final Id<State>ID=new Id<>(Identifier.of("witchersbestiary:fist_state"));public static final PacketCodec<RegistryByteBuf,State>CODEC=PacketCodec.of((p,b)->{b.writeBoolean(p.active);b.writeVarInt(p.npc);b.writeVarInt(p.stage);b.writeFloat(p.health);b.writeFloat(p.stamina);b.writeFloat(p.maxStamina);b.writeFloat(p.playerHealth);b.writeString(p.name);b.writeString(p.action);},b->new State(b.readBoolean(),b.readVarInt(),b.readVarInt(),b.readFloat(),b.readFloat(),b.readFloat(),b.readFloat(),b.readString(256),b.readString(32)));public Id<State>getId(){return ID;}}
 public record Pose(int player,boolean active,String action,int ticks) implements CustomPayload{public static final Id<Pose>ID=new Id<>(Identifier.of("witchersbestiary:fist_pose"));public static final PacketCodec<RegistryByteBuf,Pose>CODEC=PacketCodec.of((p,b)->{b.writeVarInt(p.player);b.writeBoolean(p.active);b.writeString(p.action);b.writeVarInt(p.ticks);},b->new Pose(b.readVarInt(),b.readBoolean(),b.readString(32),b.readVarInt()));public Id<Pose>getId(){return ID;}}
 public static void send(ServerPlayerEntity p,FistFights.Active a){var state=a==null?new State(false,0,0,0,0,100,0,"",""):new State(true,a.npc().getId(),a.fight().stage==FistFightSession.Stage.COUNTDOWN?Math.max(1,3-a.fight().ticks/20):0,(float)a.fight().opponent.health,(float)a.fight().player.stamina,(float)a.fight().player.maxStamina,(float)a.fight().player.health,(a.npc().hasCustomName()?a.npc().getName().getString():a.npc().getType().getTranslationKey()),a.fight().opponent.action.name());var pose=new Pose(p.getId(),a!=null,a==null?"IDLE":a.fight().player.action.name(),a==null?0:a.fight().player.actionTicks);var recipients=new java.util.HashSet<ServerPlayerEntity>(net.fabricmc.fabric.api.networking.v1.PlayerLookup.tracking(p));recipients.add(p);for(var viewer:recipients)if(net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking.canSend(viewer,Pose.ID))net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking.send(viewer,pose);if(net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking.canSend(p,State.ID))net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking.send(p,state);}
 public static void initialize(){net.fabricmc.fabric.api.networking.v1.PayloadTypeRegistry.playS2C().register(Pose.ID,Pose.CODEC);net.fabricmc.fabric.api.networking.v1.PayloadTypeRegistry.playC2S().register(Action.ID,Action.CODEC);net.fabricmc.fabric.api.networking.v1.PayloadTypeRegistry.playS2C().register(State.ID,State.CODEC);net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking.registerGlobalReceiver(Action.ID,(a,c)->c.server().execute(()->{if(a.value>=0&&a.value<=FistFightSession.Action.DODGE.ordinal())FistFights.action(c.player(),FistFightSession.Action.values()[a.value]);}));}
}
